CREATE OR REPLACE FUNCTION public.fn_get_branch_floor_maps(p_tenant_id uuid, p_organization_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid, p_status character varying DEFAULT NULL::character varying)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, branch_id uuid, name character varying, building_area character varying, floor_level character varying, description text, file_storage_key character varying, file_type character varying, file_size bigint, content_hash character varying, version integer, status character varying, review_due_at timestamp with time zone, created_by character varying, created_at timestamp with time zone, published_by character varying, published_at timestamp with time zone, supersedes_map_id uuid, row_version integer, emergency_instructions text)  LANGUAGE sql  STABLE AS $function$     SELECT          id, tenant_id, organization_id, branch_id, name, building_area,         floor_level, description, file_storage_key, file_type, file_size,         content_hash, version, status, review_due_at, created_by, created_at,         published_by, published_at, supersedes_map_id, row_version, emergency_instructions     FROM branch_floor_maps     WHERE tenant_id = p_tenant_id       AND (p_organization_id IS NULL OR organization_id = p_organization_id)       AND (p_branch_id IS NULL OR branch_id = p_branch_id)       AND (p_status IS NULL OR status = p_status)     ORDER BY floor_level ASC, name ASC, version DESC; $function$ ;
